add_action( 'woocommerce_after_add_to_cart_button', 'perfectpixel_live_quantity_total' );

function perfectpixel_live_quantity_total() {
	global $product;
	if ( ! $product || ! $product->is_type( 'simple' ) || $product->is_sold_individually() ) {
		return;
	}
	$cfg = array(
		'price'    => (float) wc_get_price_to_display( $product ),
		'decimals' => wc_get_price_decimals(),
		'dec'      => wc_get_price_decimal_separator(),
		'thousand' => wc_get_price_thousand_separator(),
		'format'   => html_entity_decode( sprintf( get_woocommerce_price_format(), get_woocommerce_currency_symbol(), '%v' ) ),
	);
	?>
	<div class="perfectpixel-live-total" style="margin-top:1em;width:100%"><?php echo esc_html( '{{live_total_label}}' ); ?> <strong></strong></div>
	<script>
	( function ( box, cfg ) {
		var form  = box.closest( 'form.cart' );
		var input = form && form.querySelector( 'input.qty' );
		var out   = box.querySelector( 'strong' );
		var money = function ( n ) {
			var parts = n.toFixed( cfg.decimals ).split( '.' );
			parts[0] = parts[0].replace( /\B(?=(\d{3})+(?!\d))/g, cfg.thousand );
			return cfg.format.replace( '%v', parts.join( cfg.dec ) );
		};
		var update = function () {
			var qty = Math.max( 0, parseFloat( input ? input.value : 1 ) || 0 );
			out.textContent = money( cfg.price * qty );
		};
		if ( input ) {
			input.addEventListener( 'input', update );
			input.addEventListener( 'change', update );
		}
		update();
	} )( document.currentScript.previousElementSibling, <?php echo wp_json_encode( $cfg ); ?> );
	</script>
	<?php
}
